package com.primehr.succession.application;

import com.primehr.integration.humanresource.*;
import com.primehr.shared.audit.PrimeHrAuditService;
import com.primehr.shared.exception.*;
import com.primehr.succession.api.SuccessionFoundationDtos.*;
import com.primehr.succession.domain.*;
import com.primehr.succession.infrastructure.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal; import java.time.*; import java.util.*;

@Service @Transactional
public class SuccessionFoundationServiceImpl implements SuccessionFoundationService {
 private final SuccessionGovernancePolicyRepository policyRoots; private final SuccessionGovernancePolicyVersionRepository policies;
 private final SuccessionReadinessScaleRepository scaleRoots; private final SuccessionReadinessScaleVersionRepository scales; private final SuccessionReadinessLevelRepository levels;
 private final SuccessionCommitteeCharterRepository charterRoots; private final SuccessionCommitteeCharterVersionRepository charters; private final SuccessionCommitteeMemberRepository members; private final SuccessionCommitteeConflictRepository conflicts;
 private final HumanResourcePerformanceParticipantClient hr; private final PrimeHrAuditService audit;
 public SuccessionFoundationServiceImpl(SuccessionGovernancePolicyRepository policyRoots,SuccessionGovernancePolicyVersionRepository policies,SuccessionReadinessScaleRepository scaleRoots,SuccessionReadinessScaleVersionRepository scales,SuccessionReadinessLevelRepository levels,SuccessionCommitteeCharterRepository charterRoots,SuccessionCommitteeCharterVersionRepository charters,SuccessionCommitteeMemberRepository members,SuccessionCommitteeConflictRepository conflicts,HumanResourcePerformanceParticipantClient hr,PrimeHrAuditService audit){this.policyRoots=policyRoots;this.policies=policies;this.scaleRoots=scaleRoots;this.scales=scales;this.levels=levels;this.charterRoots=charterRoots;this.charters=charters;this.members=members;this.conflicts=conflicts;this.hr=hr;this.audit=audit;}

 @Override @Transactional(readOnly=true) public List<PolicyResponse> policies(String a){return policies.findByAgencyIdOrderByCreatedAtDesc(a).stream().map(v->policyResponse(a,v)).toList();}
 @Override @Transactional(readOnly=true) public PolicyResponse getPolicy(String a,String id){return policyResponse(a,policy(a,id));}
 @Override @Transactional(readOnly=true) public PolicyResponse effectivePolicy(String a,LocalDate on){return policies.findByAgencyIdAndStatus(a,SuccessionDefinitionStatus.PUBLISHED).stream().filter(v->v.effectiveOn(on)).findFirst().map(v->policyResponse(a,v)).orElseThrow(()->new ResourceNotFoundException("No succession policy is effective on the requested date"));}
 @Override public PolicyResponse createPolicy(String a,PolicyInput i,String c){requireNew(i.recordVersion());if(policyRoots.existsByAgencyIdAndNormalizedCode(a,norm(i.code())))throw new IllegalArgumentException("Succession policy code already exists");var root=policyRoots.saveAndFlush(new SuccessionGovernancePolicy(a,i.code()));var v=policies.saveAndFlush(newPolicy(a,root.getId(),1,null,i));var out=policyResponse(a,v);record(a,"CREATE_SUCCESSION_POLICY_DRAFT","SUCCESSION_POLICY_VERSION",v,null,out,null,c);return out;}
 @Override public PolicyResponse updatePolicy(String a,String id,PolicyInput i,String c){var v=policy(a,id);requireVersion(v.getVersion(),i.recordVersion());stable(policyRoot(a,v.getPolicyId()).getCode(),i.code());var before=policyResponse(a,v);v.update(i.title(),i.description(),i.legalBasis(),i.policyReference(),i.privacyNotice(),i.eligibilityGuidance(),i.evidenceRequirements(),i.reviewIntervalMonths(),i.membershipValidityMonths(),i.minimumAggregateCohort(),i.requiresEmployeeNotice(),i.requiresEmployeeConsent(),i.allowsSelfExpression(),i.requiresCommitteeReview(),i.requiresAgencyHeadDecision());v=policies.saveAndFlush(v);var out=policyResponse(a,v);record(a,"UPDATE_SUCCESSION_POLICY_DRAFT","SUCCESSION_POLICY_VERSION",v,before,out,null,c);return out;}
 @Override public PolicyResponse revisePolicy(String a,String id,Transition i,String c){var p=policy(a,id);requireVersion(p.getVersion(),i.recordVersion());published(p);int next=policies.findByAgencyIdAndPolicyIdOrderByDefinitionVersionDesc(a,p.getPolicyId()).stream().mapToInt(SuccessionGovernancePolicyVersion::getDefinitionVersion).max().orElse(0)+1;var v=policies.saveAndFlush(new SuccessionGovernancePolicyVersion(a,p.getPolicyId(),next,p.getId(),p.getTitle(),p.getDescription(),p.getLegalBasis(),p.getPolicyReference(),p.getPrivacyNotice(),p.getEligibilityGuidance(),p.getEvidenceRequirements(),p.getReviewIntervalMonths(),p.getMembershipValidityMonths(),p.getMinimumAggregateCohort(),p.isRequiresEmployeeNotice(),p.isRequiresEmployeeConsent(),p.isAllowsSelfExpression(),p.isRequiresCommitteeReview(),p.isRequiresAgencyHeadDecision()));var out=policyResponse(a,v);record(a,"REVISE_SUCCESSION_POLICY","SUCCESSION_POLICY_VERSION",v,null,out,i.reason(),c);return out;}
 @Override public PolicyResponse publishPolicy(String a,String id,Publish i,String c){var v=policy(a,id);requireVersion(v.getVersion(),i.recordVersion());var prior=v.getSupersedesId()==null?null:policy(a,v.getSupersedesId());validatePublish(i,prior,policies.findByAgencyIdAndStatus(a,SuccessionDefinitionStatus.PUBLISHED),v.getId());var before=policyResponse(a,v);publish(v,prior,i,policies);var out=policyResponse(a,v);record(a,"PUBLISH_SUCCESSION_POLICY","SUCCESSION_POLICY_VERSION",v,before,out,i.reason(),c);return out;}
 @Override public PolicyResponse retirePolicy(String a,String id,Transition i,String c){var v=policy(a,id);requireVersion(v.getVersion(),i.recordVersion());var before=policyResponse(a,v);v.retire(audit.currentActor(),i.reason(),Instant.now());policies.saveAndFlush(v);var out=policyResponse(a,v);record(a,"RETIRE_SUCCESSION_POLICY","SUCCESSION_POLICY_VERSION",v,before,out,i.reason(),c);return out;}

 @Override @Transactional(readOnly=true) public List<ScaleResponse> scales(String a){return scales.findByAgencyIdOrderByCreatedAtDesc(a).stream().map(v->scaleResponse(a,v)).toList();}
 @Override @Transactional(readOnly=true) public ScaleResponse getScale(String a,String id){return scaleResponse(a,scale(a,id));}
 @Override public ScaleResponse createScale(String a,ScaleInput i,String c){requireNew(i.recordVersion());if(scaleRoots.existsByAgencyIdAndNormalizedCode(a,norm(i.code())))throw new IllegalArgumentException("Readiness scale code already exists");var root=scaleRoots.saveAndFlush(new SuccessionReadinessScale(a,i.code()));var v=scales.saveAndFlush(new SuccessionReadinessScaleVersion(a,root.getId(),1,null,i.title(),i.description(),i.decisionGuidance(),i.requiresNarrative()));var out=scaleResponse(a,v);record(a,"CREATE_SUCCESSION_SCALE_DRAFT","SUCCESSION_SCALE_VERSION",v,null,out,null,c);return out;}
 @Override public ScaleResponse updateScale(String a,String id,ScaleInput i,String c){var v=scale(a,id);requireVersion(v.getVersion(),i.recordVersion());stable(scaleRoot(a,v.getScaleId()).getCode(),i.code());var before=scaleResponse(a,v);v.update(i.title(),i.description(),i.decisionGuidance(),i.requiresNarrative());scales.saveAndFlush(v);var out=scaleResponse(a,v);record(a,"UPDATE_SUCCESSION_SCALE_DRAFT","SUCCESSION_SCALE_VERSION",v,before,out,null,c);return out;}
 @Override public ScaleResponse replaceLevels(String a,String id,LevelsInput i,String c){var v=scale(a,id);requireVersion(v.getVersion(),i.recordVersion());validateLevels(i.levels());var before=scaleResponse(a,v);levels.deleteByAgencyIdAndScaleVersionId(a,id);levels.flush();levels.saveAll(i.levels().stream().map(x->new SuccessionReadinessLevel(a,id,x.code(),x.label(),x.description(),x.developmentGuidance(),x.reviewAfterMonths(),x.allowsPoolMembership(),x.displayOrder())).toList());v.levelsChanged();scales.saveAndFlush(v);var out=scaleResponse(a,v);record(a,"REPLACE_SUCCESSION_READINESS_LEVELS","SUCCESSION_SCALE_VERSION",v,before,out,null,c);return out;}
 @Override public ScaleResponse reviseScale(String a,String id,Transition i,String c){var p=scale(a,id);requireVersion(p.getVersion(),i.recordVersion());published(p);int next=scales.findByAgencyIdAndScaleIdOrderByDefinitionVersionDesc(a,p.getScaleId()).stream().mapToInt(SuccessionReadinessScaleVersion::getDefinitionVersion).max().orElse(0)+1;var v=scales.saveAndFlush(new SuccessionReadinessScaleVersion(a,p.getScaleId(),next,p.getId(),p.getTitle(),p.getDescription(),p.getDecisionGuidance(),p.isRequiresNarrative()));var old=levels.findByAgencyIdAndScaleVersionIdOrderByDisplayOrder(a,id);if(!old.isEmpty()){levels.saveAll(old.stream().map(x->new SuccessionReadinessLevel(a,v.getId(),x.getCode(),x.getLabel(),x.getDescription(),x.getDevelopmentGuidance(),x.getReviewAfterMonths(),x.isAllowsPoolMembership(),x.getDisplayOrder())).toList());v.levelsChanged();scales.saveAndFlush(v);}var out=scaleResponse(a,v);record(a,"REVISE_SUCCESSION_SCALE","SUCCESSION_SCALE_VERSION",v,null,out,i.reason(),c);return out;}
 @Override public ScaleResponse publishScale(String a,String id,Publish i,String c){var v=scale(a,id);requireVersion(v.getVersion(),i.recordVersion());validateLevelsForPublish(a,id);var prior=v.getSupersedesId()==null?null:scale(a,v.getSupersedesId());validatePublish(i,prior,scales.findByAgencyIdAndStatus(a,SuccessionDefinitionStatus.PUBLISHED),v.getId());var before=scaleResponse(a,v);publish(v,prior,i,scales);var out=scaleResponse(a,v);record(a,"PUBLISH_SUCCESSION_SCALE","SUCCESSION_SCALE_VERSION",v,before,out,i.reason(),c);return out;}
 @Override public ScaleResponse retireScale(String a,String id,Transition i,String c){var v=scale(a,id);requireVersion(v.getVersion(),i.recordVersion());var before=scaleResponse(a,v);v.retire(audit.currentActor(),i.reason(),Instant.now());scales.saveAndFlush(v);var out=scaleResponse(a,v);record(a,"RETIRE_SUCCESSION_SCALE","SUCCESSION_SCALE_VERSION",v,before,out,i.reason(),c);return out;}

 @Override @Transactional(readOnly=true) public List<CharterResponse> charters(String a){return charters.findByAgencyIdOrderByCreatedAtDesc(a).stream().map(v->charterResponse(a,v)).toList();}
 @Override @Transactional(readOnly=true) public CharterResponse getCharter(String a,String id){return charterResponse(a,charter(a,id));}
 @Override public CharterResponse createCharter(String a,CharterInput i,String c){requireNew(i.recordVersion());if(charterRoots.existsByAgencyIdAndNormalizedCode(a,norm(i.code())))throw new IllegalArgumentException("Committee charter code already exists");var root=charterRoots.saveAndFlush(new SuccessionCommitteeCharter(a,i.code()));var v=charters.saveAndFlush(newCharter(a,root.getId(),1,null,i));var out=charterResponse(a,v);record(a,"CREATE_SUCCESSION_CHARTER_DRAFT","SUCCESSION_CHARTER_VERSION",v,null,out,null,c);return out;}
 @Override public CharterResponse updateCharter(String a,String id,CharterInput i,String c){var v=charter(a,id);requireVersion(v.getVersion(),i.recordVersion());stable(charterRoot(a,v.getCharterId()).getCode(),i.code());var before=charterResponse(a,v);v.update(i.title(),i.description(),i.legalBasis(),i.authorityReference(),i.quorumType(),i.quorumValue(),i.requiresSecretariat(),i.requiresAgencyHeadDecision(),i.conflictDeclarationRequired());charters.saveAndFlush(v);var out=charterResponse(a,v);record(a,"UPDATE_SUCCESSION_CHARTER_DRAFT","SUCCESSION_CHARTER_VERSION",v,before,out,null,c);return out;}
 @Override public CharterResponse replaceRoster(String a,String id,RosterInput i,String token,String c){var v=charter(a,id);requireVersion(v.getVersion(),i.recordVersion());validateRoster(v,i.members());var before=charterResponse(a,v);var resolved=i.members().stream().map(x->new SuccessionCommitteeMember(a,id,hr.getByEmployeeNo(x.employeeNo(),token),x.memberRole(),x.votingMember(),x.effectiveFrom(),x.effectiveTo())).toList();members.deleteByAgencyIdAndCharterVersionId(a,id);members.flush();members.saveAll(resolved);v.rosterChanged();charters.saveAndFlush(v);var out=charterResponse(a,v);record(a,"REPLACE_SUCCESSION_COMMITTEE_ROSTER","SUCCESSION_CHARTER_VERSION",v,before,out,null,c);return out;}
 @Override public CharterResponse reviseCharter(String a,String id,Transition i,String c){var p=charter(a,id);requireVersion(p.getVersion(),i.recordVersion());published(p);int next=charters.findByAgencyIdAndCharterIdOrderByDefinitionVersionDesc(a,p.getCharterId()).stream().mapToInt(SuccessionCommitteeCharterVersion::getDefinitionVersion).max().orElse(0)+1;var v=charters.saveAndFlush(new SuccessionCommitteeCharterVersion(a,p.getCharterId(),next,p.getId(),p.getTitle(),p.getDescription(),p.getLegalBasis(),p.getAuthorityReference(),p.getQuorumType(),p.getQuorumValue(),p.isRequiresSecretariat(),p.isRequiresAgencyHeadDecision(),p.isConflictDeclarationRequired()));var out=charterResponse(a,v);record(a,"REVISE_SUCCESSION_CHARTER","SUCCESSION_CHARTER_VERSION",v,null,out,i.reason(),c);return out;}
 @Override public CharterResponse publishCharter(String a,String id,Publish i,String c){var v=charter(a,id);requireVersion(v.getVersion(),i.recordVersion());validateRosterForPublish(a,v);var prior=v.getSupersedesId()==null?null:charter(a,v.getSupersedesId());validatePublish(i,prior,charters.findByAgencyIdAndStatus(a,SuccessionDefinitionStatus.PUBLISHED),v.getId());var before=charterResponse(a,v);publish(v,prior,i,charters);var out=charterResponse(a,v);record(a,"PUBLISH_SUCCESSION_CHARTER","SUCCESSION_CHARTER_VERSION",v,before,out,i.reason(),c);return out;}
 @Override public CharterResponse retireCharter(String a,String id,Transition i,String c){var v=charter(a,id);requireVersion(v.getVersion(),i.recordVersion());var before=charterResponse(a,v);v.retire(audit.currentActor(),i.reason(),Instant.now());charters.saveAndFlush(v);var out=charterResponse(a,v);record(a,"RETIRE_SUCCESSION_CHARTER","SUCCESSION_CHARTER_VERSION",v,before,out,i.reason(),c);return out;}

 @Override @Transactional(readOnly=true) public List<ConflictResponse> conflicts(String a,String id){charter(a,id);return conflicts.findByAgencyIdAndCharterVersionIdOrderByDeclaredAtDesc(a,id).stream().map(this::conflictResponse).toList();}
 @Override public ConflictResponse declareConflict(String a,String id,ConflictInput i,String c){charter(a,id);if(!members.existsByAgencyIdAndCharterVersionIdAndEmployeeNoIgnoreCase(a,id,i.declaringEmployeeNo()))throw new IllegalArgumentException("Declaring employee must be on the committee roster");if(conflicts.existsByAgencyIdAndCharterVersionIdAndDeclaringEmployeeNoIgnoreCaseAndRelatedEmployeeNoIgnoreCaseAndStatus(a,id,i.declaringEmployeeNo(),i.relatedEmployeeNo(),SuccessionCommitteeConflict.Status.ACTIVE))throw new IllegalArgumentException("An active conflict already exists");var v=conflicts.saveAndFlush(new SuccessionCommitteeConflict(a,id,i.declaringEmployeeNo(),i.relatedEmployeeNo(),i.conflictType(),i.details(),audit.currentActor(),Instant.now()));var out=conflictResponse(v);audit.record(a,"DECLARE_SUCCESSION_CONFLICT","SUCCESSION_COMMITTEE_CONFLICT",v.getId(),null,v.getVersion(),null,out,i.details(),c);return out;}
 @Override public ConflictResponse resolveConflict(String a,String id,ResolveConflict i,String c){var v=conflicts.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Committee conflict not found"));requireVersion(v.getVersion(),i.recordVersion());var before=conflictResponse(v);v.resolve(audit.currentActor(),i.reason(),Instant.now());conflicts.saveAndFlush(v);var out=conflictResponse(v);audit.record(a,"RESOLVE_SUCCESSION_CONFLICT","SUCCESSION_COMMITTEE_CONFLICT",v.getId(),null,v.getVersion(),before,out,i.reason(),c);return out;}

 private SuccessionGovernancePolicyVersion newPolicy(String a,String root,int version,String sup,PolicyInput i){return new SuccessionGovernancePolicyVersion(a,root,version,sup,i.title(),i.description(),i.legalBasis(),i.policyReference(),i.privacyNotice(),i.eligibilityGuidance(),i.evidenceRequirements(),i.reviewIntervalMonths(),i.membershipValidityMonths(),i.minimumAggregateCohort(),i.requiresEmployeeNotice(),i.requiresEmployeeConsent(),i.allowsSelfExpression(),i.requiresCommitteeReview(),i.requiresAgencyHeadDecision());}
 private SuccessionCommitteeCharterVersion newCharter(String a,String root,int version,String sup,CharterInput i){return new SuccessionCommitteeCharterVersion(a,root,version,sup,i.title(),i.description(),i.legalBasis(),i.authorityReference(),i.quorumType(),i.quorumValue(),i.requiresSecretariat(),i.requiresAgencyHeadDecision(),i.conflictDeclarationRequired());}
 private PolicyResponse policyResponse(String a,SuccessionGovernancePolicyVersion v){return new PolicyResponse(v.getId(),v.getPolicyId(),policyRoot(a,v.getPolicyId()).getCode(),v.getTitle(),v.getDescription(),v.getLegalBasis(),v.getPolicyReference(),v.getPrivacyNotice(),v.getEligibilityGuidance(),v.getEvidenceRequirements(),v.getReviewIntervalMonths(),v.getMembershipValidityMonths(),v.getMinimumAggregateCohort(),v.isRequiresEmployeeNotice(),v.isRequiresEmployeeConsent(),v.isAllowsSelfExpression(),v.isRequiresCommitteeReview(),v.isRequiresAgencyHeadDecision(),v.getDefinitionVersion(),v.getSupersedesId(),v.getStatus().name(),v.getEffectiveFrom(),v.getEffectiveTo(),v.getVersion());}
 private ScaleResponse scaleResponse(String a,SuccessionReadinessScaleVersion v){return new ScaleResponse(v.getId(),v.getScaleId(),scaleRoot(a,v.getScaleId()).getCode(),v.getTitle(),v.getDescription(),v.getDecisionGuidance(),v.isRequiresNarrative(),v.getLevelsRevision(),v.getDefinitionVersion(),v.getSupersedesId(),v.getStatus().name(),v.getEffectiveFrom(),v.getEffectiveTo(),v.getVersion(),levels.findByAgencyIdAndScaleVersionIdOrderByDisplayOrder(a,v.getId()).stream().map(x->new LevelResponse(x.getId(),x.getCode(),x.getLabel(),x.getDescription(),x.getDevelopmentGuidance(),x.getReviewAfterMonths(),x.isAllowsPoolMembership(),x.getDisplayOrder())).toList());}
 private CharterResponse charterResponse(String a,SuccessionCommitteeCharterVersion v){return new CharterResponse(v.getId(),v.getCharterId(),charterRoot(a,v.getCharterId()).getCode(),v.getTitle(),v.getDescription(),v.getLegalBasis(),v.getAuthorityReference(),v.getQuorumType().name(),v.getQuorumValue(),v.isRequiresSecretariat(),v.isRequiresAgencyHeadDecision(),v.isConflictDeclarationRequired(),v.getRosterRevision(),v.getDefinitionVersion(),v.getSupersedesId(),v.getStatus().name(),v.getEffectiveFrom(),v.getEffectiveTo(),v.getVersion(),members.findByAgencyIdAndCharterVersionIdOrderByMemberRole(a,v.getId()).stream().map(x->new MemberResponse(x.getId(),x.getEmployeeId(),x.getEmployeeNo(),x.getDisplayName(),x.getAppointmentId(),x.getJobPositionId(),x.getPlantillaId(),x.getMemberRole().name(),x.isVotingMember(),x.getEffectiveFrom(),x.getEffectiveTo(),x.getSourceFingerprint(),x.getSourceFetchedAt())).toList());}
 private ConflictResponse conflictResponse(SuccessionCommitteeConflict v){return new ConflictResponse(v.getId(),v.getCharterVersionId(),v.getDeclaringEmployeeNo(),v.getRelatedEmployeeNo(),v.getConflictType().name(),v.getDetails(),v.getStatus().name(),v.getDeclaredBy(),v.getDeclaredAt(),v.getResolvedBy(),v.getResolvedAt(),v.getResolutionReason(),v.getVersion());}
 private void validateLevels(List<LevelInput> xs){if(xs.size()<2)throw new IllegalArgumentException("Readiness scale requires at least two levels");Set<String> codes=new HashSet<>();Set<Integer> orders=new HashSet<>();boolean allowed=false;boolean withheld=false;for(var x:xs){if(!codes.add(norm(x.code()))||!orders.add(x.displayOrder()))throw new IllegalArgumentException("Readiness level codes and order must be unique");allowed|=x.allowsPoolMembership();withheld|=!x.allowsPoolMembership();}if(!allowed||!withheld)throw new IllegalArgumentException("Scale must distinguish eligible and not-yet-eligible readiness");}
 private void validateLevelsForPublish(String a,String id){var xs=levels.findByAgencyIdAndScaleVersionIdOrderByDisplayOrder(a,id);validateLevels(xs.stream().map(x->new LevelInput(x.getCode(),x.getLabel(),x.getDescription(),x.getDevelopmentGuidance(),x.getReviewAfterMonths(),x.isAllowsPoolMembership(),x.getDisplayOrder())).toList());}
 private void validateRoster(SuccessionCommitteeCharterVersion v,List<MemberInput> xs){Set<String> nos=new HashSet<>();long chair=0,secretary=0,voting=0;for(var x:xs){if(!nos.add(norm(x.employeeNo())))throw new IllegalArgumentException("Committee employees must be unique");if(x.memberRole()==SuccessionCommitteeMember.Role.CHAIR)chair++;if(x.memberRole()==SuccessionCommitteeMember.Role.SECRETARIAT)secretary++;if(x.votingMember())voting++;}if(chair!=1)throw new IllegalArgumentException("Roster requires exactly one chair");if(v.isRequiresSecretariat()&&secretary<1)throw new IllegalArgumentException("Roster requires a secretariat");if(voting<1)throw new IllegalArgumentException("Roster requires a voting member");if(v.getQuorumType()==SuccessionCommitteeCharterVersion.QuorumType.COUNT&&v.getQuorumValue().compareTo(BigDecimal.valueOf(voting))>0)throw new IllegalArgumentException("Count quorum cannot exceed voting membership");}
 private void validateRosterForPublish(String a,SuccessionCommitteeCharterVersion v){var xs=members.findByAgencyIdAndCharterVersionIdOrderByMemberRole(a,v.getId());validateRoster(v,xs.stream().map(x->new MemberInput(x.getEmployeeNo(),x.getMemberRole(),x.isVotingMember(),x.getEffectiveFrom(),x.getEffectiveTo())).toList());}
 private <T extends SuccessionVersionedDefinition> void validatePublish(Publish i,T prior,List<T> existing,String id){if(prior==null&&existing.stream().anyMatch(x->!x.getId().equals(id)))throw new IllegalLifecycleTransitionException("A published definition already exists; create a revision");if(prior!=null&&!i.effectiveFrom().isAfter(prior.getEffectiveFrom()))throw new IllegalArgumentException("Revision effectivity must follow predecessor");}
 private <T extends SuccessionVersionedDefinition> void publish(T v,T prior,Publish i,org.springframework.data.jpa.repository.JpaRepository<T,String> repo){Instant now=Instant.now();v.publish(i.effectiveFrom(),i.effectiveTo(),audit.currentActor(),now);repo.saveAndFlush(v);if(prior!=null){prior.supersede(i.effectiveFrom(),audit.currentActor(),now);repo.saveAndFlush(prior);}}
 private SuccessionGovernancePolicyVersion policy(String a,String id){return policies.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Succession policy not found"));} private SuccessionGovernancePolicy policyRoot(String a,String id){return policyRoots.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Succession policy root not found"));}
 private SuccessionReadinessScaleVersion scale(String a,String id){return scales.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Readiness scale not found"));} private SuccessionReadinessScale scaleRoot(String a,String id){return scaleRoots.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Readiness scale root not found"));}
 private SuccessionCommitteeCharterVersion charter(String a,String id){return charters.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Committee charter not found"));} private SuccessionCommitteeCharter charterRoot(String a,String id){return charterRoots.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Committee charter root not found"));}
 private static void requireNew(Long v){if(v!=null)throw new IllegalArgumentException("recordVersion must be omitted for new records");} private static void requireVersion(long current,Long supplied){if(supplied==null||current!=supplied)throw new OptimisticConflictException("Record version is stale");} private static void stable(String a,String b){if(!norm(a).equals(norm(b)))throw new IllegalArgumentException("Definition code cannot change");} private static void published(SuccessionVersionedDefinition v){if(v.getStatus()!=SuccessionDefinitionStatus.PUBLISHED)throw new IllegalLifecycleTransitionException("Only published definitions may be revised");} private static String norm(String x){return x==null?"":x.trim().toUpperCase(Locale.ROOT);}
 private void record(String a,String action,String type,SuccessionVersionedDefinition v,Object before,Object after,String reason,String c){audit.record(a,action,type,v.getId(),v.getDefinitionVersion(),v.getVersion(),before,after,reason,c);}
}
